const CAPS=[
 {icon:Sun,title:'Start prepared',text:'A concise morning briefing brings the day’s meeting context together.',points:['Weekday briefing at 06:55 (Australia/Sydney), a full paragraph overview plus your meeting list','Shows each meeting with a few preparation points','Private, cancelled and all-day events are left out before processing']},
 {icon:FileText,title:'Keep decisions clear',text:'Draft minutes capture decisions and evidence for a person to review.',points:['Built from official Teams transcripts or an authorized audio upload','Every decision and action links back to evidence in the transcript','Minutes stay in draft until a person reviews and saves a version']},
 {icon:ListChecks,title:'Follow through',text:'Action items keep ownership and next steps visible after the meeting.',points:['Each action has an owner, a due date and a status','Move items from proposed to in progress to completed','One list across all of your meetings']}];
