 const cameFromApp=React.useRef(false),lastScroll=React.useRef(0);
 useEffect(()=>{const h=()=>{if(/^#\/room\//.test(location.hash))cameFromApp.current=true;setHash(location.hash)};const sc=()=>{if(!/^#\/room\//.test(location.hash))lastScroll.current=window.scrollY};window.addEventListener('hashchange',h);window.addEventListener('scroll',sc,{passive:true});return()=>{window.removeEventListener('hashchange',h);window.removeEventListener('scroll',sc)}},[]);
 const inRoom=/^#\/room\//.test(hash);
 useEffect(()=>{if(!inRoom&&cameFromApp.current){cameFromApp.current=false;const y=lastScroll.current;requestAnimationFrame(()=>window.scrollTo(0,y))}},[inRoom]);
