 useEffect(()=>{if(!menu)return;const esc=e=>{if(e.key==='Escape')setMenu(false)};window.addEventListener('keydown',esc);return()=>window.removeEventListener('keydown',esc)},[menu]);
 const [token,setToken]=useState(initialToken),[username,setUsername]=useState('admin'),[password,setPassword]=useState(''),[showLogin,setShowLogin]=useState(false),[cap,setCap]=useState(0),[step,setStep]=useState(0),[showTop,setShowTop]=useState(false),[section,setSection]=useState('top'),[loginError,setLoginError]=useState(''),[loginFor,setLoginFor]=useState(''),[authMode,setAuthMode]=useState<'login'|'signup'>('login'),[fullName,setFullName]=useState(''),[email,setEmail]=useState(''),[confirm,setConfirm]=useState(''),[noAccount,setNoAccount]=useState(false),[canSignup,setCanSignup]=useState(import.meta.env.VITE_DEMO_MODE==='true'),[loginBusy,setLoginBusy]=useState(false),[showPw,setShowPw]=useState(false),[user,setUser]=useState<User|null>(null),[page,setPage]=useState('Dashboard'),[dashboard,setDashboard]=useState<any>(null),[meetings,setMeetings]=useState<Meeting[]>([]),[actions,setActions]=useState<ActionItem[]>([]),[briefings,setBriefings]=useState<Briefing[]>([]),[runs,setRuns]=useState<WorkflowRun[]>([]),[settings,setSettings]=useState<any>(null),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false),[preview,setPreview]=useState<any>(null),[minutes,setMinutes]=useState<any[]>([]),[transcript,setTranscript]=useState<any>(null),[selectedMeeting,setSelectedMeeting]=useState('');
 const request=useCallback(async(path,options={})=>{let response;try{response=await fetch(API+path,{...options,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(token?{Authorization:`Bearer ${token}`}:{}) ,...(options.headers||{})}})}catch{throw new Error('Cannot reach the Meeting Intelligence server. Check that it is still running (the black console window must stay open), then try again.')}let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.detail||`Request failed (${response.status})`);return data},[token]);
 useEffect(()=>{if(!notice)return;const t=setTimeout(()=>setNotice(''),8000);return()=>clearTimeout(t)},[notice]);
 const load=useCallback(async()=>{if(!token)return;setBusy(true);try{const me=await request('/auth/me');setUser(me);request('/features').then(setFeatures).catch(()=>{});const names=['dashboard','meetings','action items','briefings','run history'];const res=await Promise.allSettled([request('/dashboard'),request('/meetings'),request('/action-items'),request('/briefings'),me.role==='admin'?request('/runs'):Promise.resolve([])]);const [d,m,a,b,r]=res;if(d.status==='fulfilled')setDashboard(d.value);if(m.status==='fulfilled')setMeetings(m.value);if(a.status==='fulfilled')setActions(a.value);if(b.status==='fulfilled')setBriefings(b.value);if(r.status==='fulfilled')setRuns(r.value);const failed=res.map((x,k)=>x.status==='rejected'?names[k]:'').filter(Boolean);if(failed.length&&failed.length<res.length)setNotice(`Could not load: ${failed.join(', ')}.`)}catch(e){if(/401|Invalid|expired|Authentication/i.test(e.message)){setToken('');setUser(null)}setNotice(e.message)}finally{setBusy(false)}},[token,request]);
 useEffect(()=>{load()},[load]);
 useEffect(()=>{if(!token)return;const t=setInterval(()=>{if(document.visibilityState==='visible')load()},300000);const onVis=()=>{if(document.visibilityState==='visible')load()};document.addEventListener('visibilitychange',onVis);return()=>{clearInterval(t);document.removeEventListener('visibilitychange',onVis)}},[token,load]);
 const go=(id:string)=>{if(id==='top'){window.scrollTo({top:0,behavior:'smooth'});return}document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})};
