 const login=async(event?)=>{event?.preventDefault();if(loginBusy)return;setLoginError('');setNoAccount(false);const demo=import.meta.env.VITE_DEMO_MODE==='true';if(demo&&(!username.trim()||!password)){setLoginError(!username.trim()?'Enter your user ID or email.':'Enter your password.');return}setLoginBusy(true);try{if(demo){const data=await authPost('/auth/local-login',{username:username.trim(),password});setToken(data.access_token);setPassword('');setShowLogin(false);setNotice('')}else{await msal.loginRedirect({scopes:[import.meta.env.VITE_ENTRA_API_SCOPE||`api://${import.meta.env.VITE_ENTRA_CLIENT_ID}/access_as_user`]})}}catch(e){setLoginError(e.message||'Sign-in failed.');if(e.code==='no_account')setNoAccount(true)}finally{setLoginBusy(false)}};
 const signup=async(event?)=>{event?.preventDefault();if(loginBusy)return;setLoginError('');const name=fullName.trim(),mail=email.trim();if(!name){setLoginError('Enter your full name.');return}if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(mail)){setLoginError('Enter a valid email address.');return}if(password.length<8){setLoginError('Password must be at least 8 characters.');return}if(password!==confirm){setLoginError('The two passwords do not match.');return}setLoginBusy(true);try{const data=await authPost('/auth/signup',{name,email:mail,password});setToken(data.access_token);setPassword('');setConfirm('');setFullName('');setEmail('');setShowLogin(false);setNotice('')}catch(e){setLoginError(e.message||'Sign-up failed.');if(e.code==='exists')setUsername(mail)}finally{setLoginBusy(false)}};
 const logout=()=>{setToken('');setUser(null);setDashboard(null);setMeetings([]);setActions([]);setBriefings([]);setRuns([]);setSettings(null);setPage('Dashboard');setNotice('');setPassword('');setShowLogin(false);if(import.meta.env.VITE_DEMO_MODE!=='true'){try{msal?.logoutRedirect?.()}catch{}}};
 const download=async(path:string,name:string)=>{try{const r=await fetch(API+path,{headers:token?{Authorization:`Bearer ${token}`}:{}});if(!r.ok)throw new Error(`Download failed (${r.status})`);const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){setNotice(e.message)}};
 const startInstant=()=>act(async()=>{const r=await request('/rooms',{method:'POST',body:JSON.stringify({base_url:location.origin+location.pathname})});location.hash='#/room/'+r.code});
